function indexTags(tags) {
  const unique = new Set();
  const counts = new Map();
  for (const raw of tags) {
    if (typeof raw !== "string") continue;
    const tag = raw.trim().toLowerCase();
    if (!tag) continue;
    unique.add(tag); counts.set(tag, (counts.get(tag) ?? 0) + 1);
  }
  return { tags: [...unique].sort(), counts: Object.fromEntries([...counts].sort()) };
}
console.log(indexTags(["JS", " css ", "js", "CSS"]));

