function createLimiter(limit, windowMs){
  const state=new Map();
  return (key,now)=>{
    const s=state.get(key);
    if(!s || now-s.startedAt>=windowMs){state.set(key,{startedAt:now,count:1});return {allowed:true,remaining:limit-1};}
    if(s.count>=limit)return {allowed:false,remaining:0};
    s.count++; return {allowed:true,remaining:limit-s.count};
  };
}
const check=createLimiter(2,1000);
console.log(check("a",0),check("a",100),check("a",200),check("a",1000));

