export const STATUSES=new Set(["open","in-progress","done"]);
export const PRIORITIES=new Set(["low","medium","high"]);
export class ValidationError extends Error{constructor(message){super(message);this.name="ValidationError";}}
export class Issue{#id;constructor({id=crypto.randomUUID(),title,description="",priority="medium",status="open",createdAt=Date.now(),updatedAt=Date.now()}){if(typeof title!=="string"||!title.trim()||title.trim().length>120)throw new ValidationError("Invalid title");if(typeof description!=="string"||description.length>1000)throw new ValidationError("Invalid description");if(!PRIORITIES.has(priority)||!STATUSES.has(status))throw new ValidationError("Invalid state");this.#id=String(id);this.title=title.trim();this.description=description;this.priority=priority;this.status=status;this.createdAt=Number(createdAt);this.updatedAt=Number(updatedAt);}get id(){return this.#id;}update(patch){return new Issue({...this.snapshot(),...patch,id:this.#id,updatedAt:Date.now()});}snapshot(){return {id:this.#id,title:this.title,description:this.description,priority:this.priority,status:this.status,createdAt:this.createdAt,updatedAt:this.updatedAt};}}
export const fromRecord=r=>new Issue(r);

