const requestPromise=req=>new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
const txPromise=tx=>new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error??new Error("aborted"));});
export async function openRepo(){const req=indexedDB.open("training-issues",1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains("issues")){const store=db.createObjectStore("issues",{keyPath:"id"});store.createIndex("status","status");}};const db=await requestPromise(req);return{list:()=>requestPromise(db.transaction("issues").objectStore("issues").getAll()),put:x=>{const tx=db.transaction("issues","readwrite");tx.objectStore("issues").put(x);return txPromise(tx)},remove:id=>{const tx=db.transaction("issues","readwrite");tx.objectStore("issues").delete(id);return txPromise(tx)},close:()=>db.close()};}

