import {Issue,fromRecord} from "./domain.js";import {initial,add,update,remove,filter,visible} from "./state.js";import {openRepo} from "./repository.js";import {render,renderStats} from "./render.js";
const form=document.querySelector("[data-form]"),list=document.querySelector("[data-list]"),input=document.querySelector("[data-filter]"),status=document.querySelector("[data-status]"),stats=document.querySelector("[data-stats]");let state=initial();const repo=await openRepo();const worker=new Worker("./analytics-worker.js",{type:"module"});
const draw=()=>{render(list,visible(state),act);worker.postMessage({issues:state.issues.map(i=>i.snapshot())});};
async function act(kind,id){try{const issue=state.issues.find(i=>i.id===id);if(!issue)return;if(kind==="delete"){state=remove(state,id);await repo.remove(id);}else{const next=issue.status==="open"?"in-progress":issue.status==="in-progress"?"done":"open";state=update(state,id,{status:next});await repo.put(state.issues.find(i=>i.id===id).snapshot());}draw();}catch(e){status.textContent=e.message;}}
form.addEventListener("submit",async e=>{e.preventDefault();try{const issue=new Issue(Object.fromEntries(new FormData(form)));state=add(state,issue);await repo.put(issue.snapshot());form.reset();status.textContent="Saved";draw();}catch(err){status.textContent=err.message;}});
input.addEventListener("input",()=>{state=filter(state,input.value);draw();});worker.onmessage=e=>renderStats(stats,e.data);
try{state=initial((await repo.list()).map(fromRecord));draw();status.textContent="Ready";}catch(e){status.textContent=e.message;}
addEventListener("beforeunload",()=>{worker.terminate();repo.close();});
